import java.util.Scanner;

public class Main {
    static final int MAXN = 300005;
    static long[][] dpArray = new long[27][MAXN];
    static int[] factorials = new int[MAXN];
    static int[] invFactorials = new int[MAXN];

    static long binPow(long base, int exp, int mod) {
        long res = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return res;
    }

    static int getPerm(int n, int m, int mod) {
        return (int)((long)factorials[n] * invFactorials[n - m] % mod);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int K = sc.nextInt();
        int MOD = sc.nextInt();

        if (n % 2 != 0) {
            System.out.println(binPow(K, n, MOD));
            sc.close();
            return;
        }

        factorials[0] = 1;
        for (int i = 1; i <= n; ++i) {
            factorials[i] = (int)((long)factorials[i - 1] * i % MOD);
        }

        invFactorials[n] = (int)binPow(factorials[n], MOD - 2, MOD);
        for (int i = n - 1; i >= 0; --i) {
            invFactorials[i] = (int)((long)invFactorials[i + 1] * (i + 1) % MOD);
        }

        for (int k = 0; k <= 26; ++k) {
            for (int i = 0; i < MAXN; ++i) {
                dpArray[k][i] = 0L;
            }
        }
        dpArray[0][0] = 1L;

        for (int k = 0; k < K; ++k) {
            for (int i = 1; i <= n; ++i) {
                if ((i & n) != i) continue;
                int block_mask = 1 << (31 - Integer.numberOfLeadingZeros(i));
                long[] currentDP = dpArray[k + 1];
                long[] prevDP = dpArray[k];
                long res = 0L;
                int j = i;
                int cnt = 0;
                while (true) {
                    int j_plus = j + block_mask;
                    res += prevDP[i ^ j_plus] * invFactorials[j_plus];
                    cnt++;
                    if (cnt == 17) {
                        res %= MOD;
                        cnt = 0;
                    }
                    if (j == 0) break;
                    j = (j - 1) & i;
                }
                currentDP[i] = res % MOD;
            }
        }

        int totalAns = 0;
        for (int i = 0; i <= K; ++i) {
            long term = ((long)factorials[n] * dpArray[i][n]) % MOD;
            term = (term * getPerm(K, i, MOD)) % MOD;
            totalAns = (totalAns + term) % MOD;
        }

        System.out.println((binPow(K, n, MOD) + MOD - totalAns) % MOD);
        sc.close();
    }
}

